import React , {useEffect, useState} from "react";

import "./styles.css"
import { getStore, parseDateMMDDYYYY, gen16CodeId,  ObjectKeys, parseFloatToDecimal, downloadCSVFromJson, qryStore, fetchEncryptStream, fetchQueue } from "../../../stores/Utils";

import { CloseModal, OpenModal } from "../../../components/DialogHRM";
import { SvgIcon_Cmpt, SearchInput_Cmpt,  CheckBoxSlide_Cmpt, LoadingColorSpinner_Cmpt } from "../../../components";
import { get_compare_invoice } from "../services/server_fetching";
import { FilterInvoicesComparePdf } from "../../Inventory/services/export_service";
import DeleteAlert from "../../Inventory/component/deleteAlert";


const Svg = SvgIcon_Cmpt();

const SearchInput = SearchInput_Cmpt();
const CheckBoxSlide = CheckBoxSlide_Cmpt();

const LoadingColorSpinner = LoadingColorSpinner_Cmpt();



const iconP = {
	1: {
		color:"var(--hrm_palette-success-fg)",
		icon: "success"
	},
	2: {
		color:"var(--hrm_palette-selected-nav-text)",
		icon: "problem"
	},
	3: {
		color:"rgb(254, 120, 23)",
		icon: "alert"
	},
	9: {
		color:"var(--hrm_palette-success-fg)",
		icon: "check_circle_outline"
	},
}


const ViewInvoiceCompare  = ({ data, item }) => {
	const [, set_obs] = useState(0);
	const [search, setSearch] = useState("");
	const [initialize, setInitialize] = useState(false);
	
	const [loading, set_loading] = useState(false);
	const [filter, setFilter] = useState(false);
	const [filterCode, setFilterCode] = useState(false);




	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			get_compare_invoice(updObs)
		}
	},[initialize]);

	const updObs =  () => {
		set_obs(gen16CodeId());
		set_loading(false);
	}

	const filterBc =  (v) => {
		
		setSearch(v)
		loading && set_loading(false);
	};
	

	const handleChange =  (v) => {
		!loading && set_loading(true);
		setSearch(v)
	}








	const closeView =  () => {
		CloseModal({id:data.modalID});
	};



	
	const reload =  () => {
		get_compare_invoice(updObs)
	};
	




	const openComprobanteFromBank =  (element) => {
		
		let modal_data = {};
		modal_data["zIndex"] = 450;
		modal_data["height"] = "80vh";
		// data['observeResize']=true;
		modal_data["props"] = { minHeight: "1vh", overlay: true };
		
		OpenModal(modal_data);
	}

	const toogleFilter =  (v) => {
		if(v===filterCode){
			setFilterCode(null)
		}else{
			setFilterCode(v)
		}
		
	};

	const printFiltered =  (v) => {
		let nArr = [];
		getStore("invoiceCmpDocs") && ObjectKeys(getStore("invoiceCmpDocs"))?.map((eleId,ind43) => {
			let element = getStore("invoiceCmpDocs")?.[eleId];
			if(search || filter){
				if(compareSearch(element, search, filter, filterCode)){
					nArr.push(element)
				}
			}
		});
		FilterInvoicesComparePdf(nArr)
	}



	const exportFiltered =  (v) => {
		let nArr = [];
		getStore("invoiceCmpDocs") && ObjectKeys(getStore("invoiceCmpDocs"))?.map((eleId,ind43) => {
			let element = getStore("invoiceCmpDocs")?.[eleId];
			if(search || filter){
				if(compareSearch(element, search, filter, filterCode)){
					let nobj = {
						fecha: element.date?parseDateMMDDYYYY(element.date):"",
						documento: element.document,
						importe: (element?.amount*1)?.toFixed(2),
						vendido: (element?.cc_d*1)?.toFixed(2),
						anticipo: (element?.hasAnticipo*1)?.toFixed(2),
						cobrado: (element?.cc_c*1)?.toFixed(2),
						saldo: (element?.saldo*1)?.toFixed(2),
						//invoiceId: element.invoiceId,
						//invoiceLinkConfirmed: element.invoiceLinkConfirmed,
						
	
					}
					nArr.push(nobj)

				}
			}
		});
		//console.log(nArr)
		downloadCSVFromJson('export_invoices_'+ gen16CodeId()+'.csv',nArr);
	}
	

	const exportAll =  (v) => {
		let nArr = [];
		let nArr2Up = [];
		getStore("invoiceCmpDocs") && ObjectKeys(getStore("invoiceCmpDocs"))?.map((eleId,ind43) => {
			let element = getStore("invoiceCmpDocs")?.[eleId];
			let saldo = parseFloatToDecimal(element?.saldo,2);

			let hasErr = saldo <0 ? 2:saldo >0 ? 3: element?.cc_c > 0 ?  1 : 2;
			if(element?.invoiceLinkConfirmed === 99){
				hasErr = 9;
			}

			let nobj = {
				fecha: element.date?parseDateMMDDYYYY(element.date):"",
				documento: element.document,
				importe: (element?.amount*1)?.toFixed(2),
				vendido: (element?.cc_d*1)?.toFixed(2),
				anticipo: (element?.hasAnticipo*1)?.toFixed(2),
				cobrado: (element?.cc_c*1)?.toFixed(2),
				saldo: (element?.saldo*1)?.toFixed(2),
				invoiceId: element.invoiceId,
				invoiceLinkConfirmed: element.invoiceLinkConfirmed,
				hasErr: hasErr
				

			}

			if(hasErr===1){
				nArr2Up.push(element.invoiceId)
			}
			
			nArr.push(nobj)
		});
		//console.log(nArr)

		console.log(nArr2Up)
		// fetchQueue(nArr2Up, confirmLink2Upd)
		downloadCSVFromJson('export_invoices_'+ gen16CodeId()+'.csv',nArr);
	}

	



	return (
		<div style={{
			maxHeight: "96vh",
			minHeight: "94vh",
			width: "94vw",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px 30px"
		}}>
			<div className="_dsplFlx ">
				<p className="title_collect">
					{ "Compare Invoices"}
				</p>
				<div className="flexSpace"/>
				{filter? 
				<div className="actionBx _dsplFlx" >
					<div className="filterCode"  onClick={()=>printFiltered()}>
						<Svg name={"printer"} color={ "#8b949e"}/>
					</div>
					<div className="filterCode"  onClick={()=>exportFiltered()}>
						<Svg name={"google-spreadsheet"} color={ "#8b949e"}/>
					</div>
				</div>
				:null}
			</div>



			<div className="_dsplFlx " style={{marginTop:14}}>
					<div  style={{marginTop:11}}>
						<SearchInput
							placeholder={"Buscar ...."} 
							width={560}
							obs={set_obs}
							fetchData={filterBc}
							loading={loading}
							change={handleChange}
							callempty={filterBc}
							keyFlds={"search_cmpInvoice"}
						/>
					</div>
					<div className="flexSpace"/>
					{filter? 
					<div className="_dsplFlx " style={{marginTop: 20, marginRight: 20}}>
						<div className="filterCode"  onClick={()=>toogleFilter(2)}>
							<Svg name={iconP[2]?.icon} color={filterCode===2? iconP[2]?.color : "#8b949e"}/>
						</div>
						<div className="filterCode" onClick={()=>toogleFilter(3)}>
							<Svg name={iconP[3]?.icon} color={filterCode===3? iconP[3]?.color: "#8b949e"}/>
						</div>
					</div>
					:null}
					<div className="_dsplFlx " style={{marginTop: 20}}>
						<CheckBoxSlide
							initvalue={filter}
							keyCode={57}
							updChange={setFilter}
						/>
						<span className={`checklabel`}>
							{"Need Attention"}
						</span>
					</div>
				</div>
			
			


				<div  style={{marginTop:14}}>

					<div className="_dsplFlx hdr_bar purple">
						<div className="tr_bar_5"> </div>
						<div className="tr_bar_15">
							Fecha
						</div>
						<div className="tr_bar_15">
							Documento
						</div>
						<div className="tr_bar_12">
							Importe
						</div>
						<div className="tr_bar_12">
							Vendido
						</div>
						
						<div className="tr_bar_12">
							Anticipo
						</div>
						<div className="tr_bar_12">
							Cobrado
						</div>
						<div className="tr_bar_12">
							Saldo
						</div>
						<div className="tr_bar_5"> </div>
					</div>
					<div className="scollVh subMHeight">
					{getStore("invoiceCmpDocs") && ObjectKeys(getStore("invoiceCmpDocs"))?.map((eleId,ind43) => {
						//Log$$(element)
						let element = getStore("invoiceCmpDocs")?.[eleId];
						
						
						if(search || filter){
							if(!compareSearch(element,search, filter, filterCode)){
								return null;
							}
						}
						
						let saldo = parseFloatToDecimal(element?.saldo,2);

						let hasErr = saldo <0 ? 2:saldo >0 ? 3: element?.cc_c > 0 ?  1 : 2;

						return(
							<ViewInvoiceItemCompare  
								key={ind43}
								eleId={eleId}
								element={element}
								hasErr={hasErr}
								reload={reload}
							/>
						) 
				})}
				</div>
			</div>
		</div>
	);
};




export default ViewInvoiceCompare;




const ViewInvoiceItemCompare  = ({ element, eleId, hasErr, reload }) => {


	

	const confirmLink = async () => {


		let bdyqInvoice = {...getStore(qryStore())?.upd_invoice};
		bdyqInvoice.params = {
			businessId:  getStore("profileUser")?.businessId,
			invoiceId: element.invoiceId
		}
		bdyqInvoice.data2update={invoiceLinkConfirmed: 99};

		const res = fetchEncryptStream(bdyqInvoice);
		const td = await res;
		if (td) {
			reload && reload();
		}
	}


	if(element?.invoiceLinkConfirmed === 99){
		hasErr = 9;
	}
	
	const openViewLink =  (modalId) => {
		let modaldata = {};
		modaldata["id"] = modalId;
		modaldata["zIndex"] = 490;
		modaldata["height"] = "40vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
		let bdyM = <div>
			<h4 className="" style={{padding: 4, margin: 0}}>
				{"El Invoice esta verificado en la contabilidad"}
			</h4>
			
		</div>

		let titleCm = <div className="_dsplFlx ">
			<div className="centerBx"  style={{padding: 4, marginRight: 20}}>
				<Svg name={"success"} color={iconP[hasErr]?.color}/>
			</div>
			<h4 className="" style={{padding: 4, margin: 0}}>
				{"Confirmar Invoice !!!"}
			</h4>
		</div>

		

		modaldata["content"] = <DeleteAlert
			label={titleCm} 
			labelColor={"var(--hrm_palette-success-fg)"} 
			body={bdyM} 
			btnConfirm={"Ok"}
			theme={"green"}
			confirm={confirmLink}
			done={((v)=>{
				v && CloseModal({id:v});
			})}
		/>
		OpenModal(modaldata);
	}

	return(
		<div className="_dsplFlx hdr_bar manual_vrfy" >

			<div className="tr_bar_5">
			<div onClick={openViewLink}>
				<Svg name={iconP[hasErr]?.icon} color={iconP[hasErr]?.color}/>
			</div>
			</div>
			<div className="tr_bar_15">
				{element?.date && parseDateMMDDYYYY(element.date)}
			</div>
			<div className="tr_bar_15 comprobanteId"  >
				{eleId}
			</div>
			<div className="tr_bar_12 ">
				{(element?.amount*1)?.toFixed(2)}
			</div>
			<div className="tr_bar_12">
				{(element?.cc_d*1)?.toFixed(2)}
			</div>
			
			<div className="tr_bar_12">
				{(element?.hasAnticipo*1)?.toFixed(2)}
			</div>
			<div className="tr_bar_12">
				{(element?.cc_c*1)?.toFixed(2)}
			</div>
			<div className="tr_bar_12">
				{(element?.saldo*1)?.toFixed(2)}
			</div>
			<div className="tr_bar_5"> </div>
		</div>
	) 
}





const compareSearch = (itm,qry, all, filterCode) =>{
	
	let isValid = false;

	if(qry){
		let srch = qry.toLowerCase();
		["amount","document", "cc_c", "cc_d", "saldo"].map(fld=>{

			if(all){
				let saldo = parseFloatToDecimal(itm?.saldo,2);
				let hasErr = saldo <0 ? 2:saldo >0 ? 3: itm?.cc_c > 0 ?  1 : 2;
				if(itm?.invoiceLinkConfirmed === 99){
					hasErr = 1;
				}
				if(filterCode){
					if(hasErr === filterCode && itm[fld] && itm[fld]?.toString()?.toLowerCase()?.indexOf(srch)>=0){
						isValid = true;
					}
				}
				else if(hasErr !== 1 && itm[fld] && itm[fld]?.toString()?.toLowerCase()?.indexOf(srch)>=0){
					isValid = true;
				}
			}
			else{
				if( itm[fld] && itm[fld]?.toString()?.toLowerCase()?.indexOf(srch)>=0){
					isValid = true;
				}
			}
			
		})
	}else{
		let saldo = parseFloatToDecimal(itm?.saldo,2);
		let hasErr = saldo <0 ? 2:saldo >0 ? 3: itm?.cc_c > 0 ?  1 : 2;
		if(itm?.invoiceLinkConfirmed === 99){
			hasErr = 1;
		}
		if(filterCode){
			if(hasErr === filterCode ){
				isValid = true;
			}
		}
		else if(hasErr !== 1){
			isValid = true;
		}
	}
	return isValid;
}





