import React, { useEffect, useState, useRef } from "react";

import { getStore,  gen16CodeId, ObjectKeys, AccountYears, setIntervalX, csvJSON, updStore} from "../../../stores/Utils";

import {SearchInput_Cmpt } from "../../../components";

import { OpenModal } from "../../../components/DialogHRM";

import "./dashboard.css"
import { AmznInvItem_Cmpt, AddAmznInv_Cmpt } from "..";
import {  getall_invoice, search_invoice } from "../services/server_fetching";
import { get_balances_by_type } from "../../CuentasContables/services/server_fetching";
import ViewInvoiceCompare from "./ViewInvoiceCompare";
import { scan_location_production } from "../../Inventory/services/server_fetching";



import all_orders from "../content/all_orders.json"
import mayor_products from "../content/mayor_products.json"

import tarifa_mensual_almacenamiento from "../content/tarifa_mensual_almacenamiento.json"




const SearchInput = SearchInput_Cmpt();


const InvoiceItem = AmznInvItem_Cmpt();

const MakeSale = AddAmznInv_Cmpt();



const coll2list = "collAmzReg2list"


const AmznInventoryDashboard  = ({ data, elmId, updObs }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);
	const [range, set_range] = useState(64);

	const [loading, set_loading] = useState(false);

	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			set_obs(gen16CodeId())
			getall_invoice(loadList);
			scan_location_production(updObs);
			get_balances_by_type("global_accounts","global_account_params",updObs);
		}
	});

	const updObs2 =  () => {
		set_obs(gen16CodeId());
	}


	const importCSV =  (event) => {
		var fileReader = new FileReader();
		fileReader.onload = function(fileLoadedEvent){
			var textFromFileLoaded = fileLoadedEvent.target.result;


			let sb = csvJSON(textFromFileLoaded);


			let gbP = {}
			let nAA = []
			sb.map(itm=>{
				let newObj = {}
				ObjectKeys(itm).map(fld=>{
					let nfld = fld?.split("\"")?.join("");
					newObj[nfld] = itm[fld]?.split("\"")?.join(""); 
				})
				let ASIN = newObj['asin'];
				//let Location = newObj['fulfillment_center'];

				//let yymm = newObj['month_of_charge'].split("-")

				//let pdate = yymm[1]+"/01/"+yymm[0];

				//let date = (new Date(pdate)).getTime();
				//newObj["date"] = date; 
				
				let k1 = ASIN;
				//let k2 = Location;

				if(!gbP[k1]){
					gbP[k1] = [];
				}
				gbP[k1].push(newObj);
				nAA.push(newObj)
			})


			
			//console.log(JSON.stringify(nAA,null,4));
		};
	  
		fileReader.readAsText(event.target.files[0], "UTF-8");
	}

	const openUpdateView =  () => {
		
	}

	const handleChange =  (v) => {
		!loading && set_loading(true)
	}

	const handle_search_invoice =  (v) => {
		set_loading(true)
		loadList(v)
	}


	const handle_getall_invoice =  (v) => {
		getall_invoice(loadList)
	}

	const cb_result1 = async (f, v) => {
		set_obs(gen16CodeId())
		
	};



	let validateNum = (v) => {
		return isNaN(v)?0:v?v*1:0;
	}

	const openSaleView =  () => {

		let objjj = {
			sales:{
				cost: 0,
				estimated_monthly_storage_fee: 0,
				sales:0,
				tax:0,
				shipping_price:0,
				shipping_tax:0
			},
			store:{
				start: 0,
				end: 0,
				shipped: 0,
				receipts: 0,
				lost: 0,
				found:0,
				transfer: 0,
				damaged: 0,
				customerReturns:0,
				vendorReturns:0,
			}
			
			
		}
		let ob_mayr = {
			
		};
		let balance = 0

		
		mayor_products.reverse().map(itm=>{
			let data = itm.Date;
			if(data === "01/2023"){
				let asin = itm.ASIN;
				let costP = itm.MSKU.split("-C")[1]?.split("-")[0];
				let cost = validateNum(costP)/100;
			
				
				if(!ob_mayr[asin]){
					ob_mayr[asin] = {
						asin: itm.ASIN,
						title: itm.Title,
						start: 0,
						end: 0,
						shipped: 0,
						receipts: 0,
						lost: 0,
						damaged: 0,
						customerReturns:0,
						vendorReturns:0,
						cost: 0,
						found:0,
						transfer: 0,
						estimated_monthly_storage_fee: 0,
						locations:{},
						orders: [],
						sales:0,
						tax:0,
						shipping_price:0,
						shipping_tax:0

					};
				}

				let loc = itm.Location;
				if(!ob_mayr[asin].locations[loc]){
					ob_mayr[asin].locations[loc] = {
						start: 0,
						end: 0,
						shipped: 0,
						receipts: 0,
						lost: 0,
						found:0,
						transfer: 0,
						estimated_monthly_storage_fee: 0,
					}
				}
				


				//ob_mayr[asin].start += validateNum(itm["StartingWarehouseBalance"]);
				///ob_mayr[asin].end += validateNum(itm["EndingWarehouseBalance"]);
				ob_mayr[asin].receipts += validateNum(itm["Receipts"]);
				ob_mayr[asin].lost += validateNum(itm["Lost"]);
				ob_mayr[asin].found += validateNum(itm["Found"]);
				ob_mayr[asin].transfer += validateNum(itm["WarehouseTransferIn/Out"]);
				ob_mayr[asin].shipped += validateNum(itm["CustomerShipments"]);
				ob_mayr[asin].damaged += validateNum(itm["Damaged"]);

				ob_mayr[asin].customerReturns += validateNum(itm["CustomerReturns"]);
				ob_mayr[asin].vendorReturns += validateNum(itm["VendorReturns"]);


					


				
				


				//ob_mayr[asin].locations[loc].start += validateNum(itm["StartingWarehouseBalance"]);
				// ob_mayr[asin].locations[loc].end +=validateNum(itm["EndingWarehouseBalance"]);
				ob_mayr[asin].locations[loc].receipts += validateNum(itm["Receipts"]);
				ob_mayr[asin].locations[loc].lost += validateNum(itm["Lost"]);
				ob_mayr[asin].locations[loc].found += validateNum(itm["Found"]);
				ob_mayr[asin].locations[loc].transfer += validateNum(itm["WarehouseTransferIn/Out"]);
				ob_mayr[asin].locations[loc].shipped += validateNum(itm["CustomerShipments"]);
				
				ob_mayr[asin].locations[loc].damaged += validateNum(itm["Damaged"]);
				ob_mayr[asin].locations[loc].customerReturns += validateNum(itm["CustomerReturns"]);
				ob_mayr[asin].locations[loc].vendorReturns += validateNum(itm["VendorReturns"]);


				

				//objjj.store.start += validateNum(itm["StartingWarehouseBalance"]);
				//objjj.store.end += validateNum(itm["EndingWarehouseBalance"]);
				objjj.store.receipts += validateNum(itm["Receipts"]);
				objjj.store.lost += validateNum(itm["Lost"]);
				objjj.store.found += validateNum(itm["Found"]);
				objjj.store.transfer += validateNum(itm["WarehouseTransferIn/Out"]);
				objjj.store.shipped += validateNum(itm["CustomerShipments"]);
				objjj.store.damaged += validateNum(itm["Damaged"]);
				objjj.store.customerReturns += validateNum(itm["CustomerReturns"]);
				objjj.store.vendorReturns += validateNum(itm["VendorReturns"]);

				

			
			}
			
		})
		tarifa_mensual_almacenamiento.map(itm=>{
			let asin = itm.asin;
			let loc = itm.fulfillment_center;
			if(!ob_mayr[asin]){
				ob_mayr[asin] = {
					asin,
					title: itm.product_name,
					start: 0,
					end: 0,
					damaged: 0,
					customerReturns:0,
					vendorReturns:0,
					shipped: 0,
					receipts: 0,
					lost: 0,
					found:0,
					transfer: 0,
					orders: [],
					sales:0,
					tax: 0,
					cost: 0,
					estimated_monthly_storage_fee: 0,
					locations:{},
					shipping_price:0,
					shipping_tax:0
				};
			}

			if(!ob_mayr[asin].locations[loc]){
				ob_mayr[asin].locations[loc] = {
					start: 0,
					end: 0,
					shipped: 0,
					receipts: 0,
					lost: 0,
					found:0,
					transfer: 0,
					estimated_monthly_storage_fee: 0,
				}
			}
			
			ob_mayr[asin].estimated_monthly_storage_fee += validateNum(itm["estimated_monthly_storage_fee"]);
			ob_mayr[asin].locations[loc].estimated_monthly_storage_fee += validateNum(itm["estimated_monthly_storage_fee"]);
			
			objjj.sales.estimated_monthly_storage_fee += validateNum(itm["estimated_monthly_storage_fee"]);
			
			
			balance -=  validateNum(itm["estimated_monthly_storage_fee"]);
			

			


		})
		all_orders.map(itm=>{
			let asin = itm.asin;
			if(!ob_mayr[asin]){
				ob_mayr[asin] = {
					asin,
					title: itm["product-name"],
					start: 0,
					end: 0,
					damaged: 0,
					customerReturns:0,
					vendorReturns:0,
					shipped: 0,
					receipts: 0,
					lost: 0,
					found:0,
					transfer: 0,
					orders: [],
					sales:0,
					tax: 0,
					cost: 0,
					estimated_monthly_storage_fee: 0,
					locations:{},
					shipping_price:0,
					shipping_tax:0
				};
			}

			let costP = itm.sku.split("-C")[1]?.split("-")[0];
			let cost = validateNum(costP)/100;



			ob_mayr?.[asin]?.orders?.push({
				"amazon-order-id": itm["amazon-order-id"],
				"item_tax": itm["item-tax"],
				"item_price": itm["item-price"],
				"item_status": itm["item-status"],
				"purchase_date": itm["purchase-date"],
				"quantity": itm["quantity"],
				"shipping_price": itm["shipping-price"],
				"shipping_tax": itm["shipping-tax"],
				"cost":cost
				
			})

			let amm = validateNum(itm["item-price"]) * validateNum(itm["quantity"]);
			let taxx = validateNum(itm["item-tax"]) * validateNum(itm["quantity"]);
			let shPrc = validateNum(itm["shipping-price"]);
			let shTax = validateNum(itm["shipping-tax"]);

		
			ob_mayr[asin].sales += amm;
			ob_mayr[asin].tax += taxx;
			ob_mayr[asin].shipping_price += shPrc;
			ob_mayr[asin].shipping_tax += shTax;


			objjj.sales.sales += amm;
			objjj.sales.tax += taxx;
			objjj.sales.shipping_price += shPrc;
			objjj.sales.shipping_tax += shTax;
			


			let saldo = amm-taxx-shPrc-shTax-cost;
			
			ob_mayr[asin].cost += cost;
			objjj.sales.cost += cost;
			balance +=  saldo;
			
		})

		updStore("ResumeByAmznProd",ob_mayr)
		updStore("ResumeByAmznBalance",balance.toFixed(2))
		updStore("ResumeAmznByEvent",objjj)
		
		
		updObs2();
	}

	const openSaleView1 =  () => {
		let dataModal = {};
		dataModal["zIndex"] = 450;
		dataModal["height"] = "80vh";
		// data['observeResize']=true;
		dataModal["props"] = { minHeight: "1vh", overlay: true };
		dataModal["content"] = 
			<MakeSale />
		
		OpenModal(dataModal);
	}


	const openCompareView =  () => {
		let dataModal = {};
		dataModal["zIndex"] = 450;
		dataModal["height"] = "80vh";
		// data['observeResize']=true;
		dataModal["props"] = { minHeight: "1vh", overlay: true };
		dataModal["content"] = 
			<ViewInvoiceCompare />
		
		OpenModal(dataModal);
	}

	const cb_result = async (f, v) => {
		if(range!==64){
			set_range(64);
		}
		else{
			set_obs(gen16CodeId())
		}
		set_loading(false);
	};
	
	const loadMore=  () => {
		set_range(v=>v+64)
	}

	const loadList =  (v) => {

		
		cb_result();
		
		
		if(v){
			let filt =filterArr(getStore("ResumeByAmznProd"),v) 
			updStore(coll2list,filt);
		}else{
			updStore(coll2list,getStore("ResumeByAmznProd"));
		}
		// filterArr
		let factor = Math.ceil(getStore(coll2list)?.length / 64);

		setIntervalX(loadMore, 1250, factor)

		setTimeout(() => {
			set_loading(false)
		}, 230);
		
	};




	

	return (

	<div className="inventoryAmzn">
		<div className="accounts_header">
			<h2>Inventory Amzn</h2>
			<div className="_dsplFlx ">
				{AccountYears()[getStore("date_current_year")]?.isClosed?null:
				<p className="group_title addBtn purple" onClick={openSaleView} >
					Add 
				</p>
				}
				
				<div className="group_title addBtn purple upl">
					Importar CSV
					<input id="fileupload" type = "file" onChange={importCSV}/>
				</div>
				
			</div>
			
		</div>
		
		<h2>Ingresos y Gastos  ${(getStore("ResumeByAmznBalance")*1).toFixed(2)} {} </h2>
		<div className="_dsplFlx ">
			<div className="bxPor ">
				<div className="total_comprobante_title">
						Ventas
				</div>
				<div className=" gray">
					<span>
						${(getStore("ResumeAmznByEvent")?.sales.sales*1).toFixed(2)}
					</span>
				</div>
			</div>
			<div className="bxPor ">
				<div className="total_comprobante_title">
					Taxes
				</div>
				<div className=" gray">
					<span>
						${(getStore("ResumeAmznByEvent")?.sales.tax*1).toFixed(2)}
					</span>
				</div>
			</div>
			<div className="bxPor red">
				<div className="total_comprobante_title">
						Costo del Producto
				</div>
				<div className=" gray">
					<span>
						${(getStore("ResumeAmznByEvent")?.sales.cost*1).toFixed(2)}
					</span>
				</div>
			</div>
			<div className="bxPor red ">
				<div className="total_comprobante_title">
					Gasto de Almacenamiento
				</div>
				<div className=" gray">
					<span>
						${(getStore("ResumeAmznByEvent")?.sales.estimated_monthly_storage_fee*1).toFixed(2)}
					</span>
				</div>
			</div>
			
			<div className="bxPor red">
				<div className="total_comprobante_title">
					Shipping
				</div>
				<div className=" gray">
					<span>
						${(getStore("ResumeAmznByEvent")?.sales.shipping_price*1).toFixed(2)}
					</span>
				</div>
			</div>
			<div className="bxPor red">
				<div className="total_comprobante_title">
					Shipping Tax
				</div>
				<div className=" gray">
					<span>
						${(getStore("ResumeAmznByEvent")?.sales.shipping_tax*1).toFixed(2)}
					</span>
				</div>
			</div>
		</div>

		<h2>Almacen</h2>
		<div className="_dsplFlx " style={{margin: 10}}>
			<div className="bxPor ">
				<div className="total_comprobante_title">
					Vendor Returns
				</div>
				<div className=" gray">
						<span>
							{(getStore("ResumeAmznByEvent")?.store.vendorReturns*1).toFixed(0)}
						</span>
				</div>
			</div>
			<div className="bxPor " >
				<div className="total_comprobante_title">
					Customer Returns
				</div>
				<div className=" gray">
					<span>
						{(getStore("ResumeAmznByEvent")?.store.customerReturns*1).toFixed(0)}
					</span>
				</div>
			</div>
			<div className="bxPor ">
				<div className="total_comprobante_title">
					Vendidos
				</div>
				<div className=" gray">
					<span>
						{(getStore("ResumeAmznByEvent")?.store.shipped*1).toFixed(0)}
					</span>
				</div>
			</div>
			<div className="bxPor ">
				<div className="total_comprobante_title">
					Transferidos
				</div>
				<div className=" gray">
					<span>
						{getStore("ResumeAmznByEvent")?.store.transfer}
					</span>
				</div>
			</div>
			<div className="bxPor ">
				<div className="total_comprobante_title">
					Recibidos
				</div>
				<div className=" gray">
					<span>
						{getStore("ResumeAmznByEvent")?.store.receipts}
					</span>
				</div>
			</div>
			<div className="bxPor ">
				<div className="total_comprobante_title">
					Perdidos
				</div>
				<div className=" gray">
					<span>
						{getStore("ResumeAmznByEvent")?.store.lost}
					</span>
				</div>
			</div>
			<div className="bxPor ">
				<div className="total_comprobante_title">
					Encontrados
				</div>
				<div className=" gray">
					<span>
						{getStore("ResumeAmznByEvent")?.store.found}
					</span>
				</div>
			</div>
		</div>
		


		<div style={{margin:90}}/>


		<div className="_dsplFlx " style={{margin:14}} >
			<SearchInput
				placeholder={"Buscar ...."} 
				width={360}
				obs={set_obs}
				fetchData={handle_search_invoice}
				loading={loading}
				change={handleChange}
				callempty={handle_getall_invoice}
				keyFlds={"searchQry"}
			/>
			<div className="flexSpace"/>

			

			
			<div className="_dsplFlx ">
				<div className="total_comprobante_title">
					No: 
				</div>
				<div className="total_comprobante gray">
					<span>
						{ObjectKeys(getStore("ResumeByAmznProd"))?.length}
					</span>
				</div>
				
			</div>
		</div>
		<div style={{margin:30}}/>
		<div className="_dsplFlx hdr_bar purple">
			<div className="tr_bar_10">
				ASIN
			</div>
			<div className="tr_bar_60">
				Product
			</div>
			<div className="tr_bar_7_5">
				
			</div>
			<div className="tr_bar_7_5">
				Qty
			</div>
			<div className="tr_bar_7_5">
				Venta
			</div>
			<div className="tr_bar_7_5">
				Cost
			</div>
			
		</div>
		<div className="invoices_container scollVh" style={{ height: "calc(98vh - 230px)"}}>
			{getStore(coll2list) && ObjectKeys(getStore(coll2list))?.map((cid, index)=>{
				return (
					<InvoiceItem 
						data={getStore(coll2list)[cid]} 
						elmId={cid} 
						key={cid}
						openUpdateView={openUpdateView}
						handleRefreshAll={handle_getall_invoice}
						show={index < range}
						index={index}
					/>
				)
			})}
		</div>
		</div>
	);
};

export default AmznInventoryDashboard;



const filterArr  = (arr, v)  => {
		
	let flAcc = []
	arr && ObjectKeys(arr).map((eId,inX)=>{
		
		let e = arr[eId];
		if(v){
			let ss = v.toLowerCase();
		
			let isV1 = e?.asin ? e?.asin?.toString().toLowerCase()?.indexOf(ss)>=0 : false;
			let isV2 = e?.title? e?.title?.toString().toLowerCase()?.indexOf(ss)>=0: false;
			
			if(isV1 || isV2){
				flAcc.push(e);
			}
		}
	});
	return flAcc
}